import type { OutcomeType } from 'prisma/zod/schemas/models/Outcome.schema';
import { describe, expect, it } from 'vitest';

import { coreSubmitPicker } from '@/lib/core/submitPicker';
import gameDayService from '@/services/GameDay';
import outcomeService from '@/services/Outcome';
import type { SubmitPickerInput } from '@/types/actions/SubmitPicker';
import type { OutcomePlayerType } from '@/types/OutcomePlayerType';

const shouldRunIntegration =
    process.env.RUN_PICKER_INTEGRATION === 'true' && !!process.env.DATABASE_URL;
const describeIntegration = shouldRunIntegration ? describe : describe.skip;

const parseGameIds = () => {
    const raw = process.env.PICKER_PARITY_GAME_IDS?.trim();
    if (!raw) return [1249];

    const ids = raw
        .split(',')
        .map((value) => Number.parseInt(value.trim(), 10))
        .filter(Number.isFinite)
        .filter((id) => id > 0);

    return ids.length > 0 ? ids : [1249];
};

const sorted = (ids: number[]) => ids.slice().sort((a, b) => a - b);

const sameTeamSet = (left: number[], right: number[]) => {
    const a = sorted(left);
    const b = sorted(right);
    if (a.length !== b.length) return false;
    return a.every((value, index) => value === b[index]);
};

interface Candidate {
    playerId: number;
    goalie: boolean;
    played: number;
    average: number;

