const sum = (values: number[]) => values.reduce((acc, value) => acc + value, 0);

const diffTuple = (
    teamAIds: number[],
    teamBIds: number[],
    byPlayerId: Map<number, Candidate>,
    unknownAgeValue: number,
) => {
    const read = (playerId: number) => {
        const candidate = byPlayerId.get(playerId);
        if (!candidate) {
            throw new Error(`Missing candidate for player ${playerId}`);
        }
        return candidate;
    };
    const teamA = teamAIds.map(read);
    const teamB = teamBIds.map(read);

    const diffGoalies =
        sum(teamA.map((player) => (player.goalie ? 1 : 0))) -
        sum(teamB.map((player) => (player.goalie ? 1 : 0)));
    const diffAverage =
        sum(teamA.map((player) => player.average)) -
        sum(teamB.map((player) => player.average));
    const diffUnknownAge =
        sum(teamA.map((player) => (player.age === null ? 1 : 0))) -
        sum(teamB.map((player) => (player.age === null ? 1 : 0)));
    const diffAge =
        sum(teamA.map((player) => player.age ?? unknownAgeValue)) -
        sum(teamB.map((player) => player.age ?? unknownAgeValue));

    return [
        Math.abs(diffGoalies),
        Math.abs(diffAverage),
        Math.abs(diffUnknownAge),
        Math.abs(diffAge),
    ];
};

const compareTuple = (left: number[], right: number[]) => {
    const maxLength = Math.max(left.length, right.length);
    for (let index = 0; index < maxLength; index++) {
        const l = left[index] ?? 0;
        const r = right[index] ?? 0;
        if (Math.abs(l - r) <= 1e-9) continue;
        return l < r ? -1 : 1;
    }
    return 0;
};

const uniqueSplits = (playerIdsInOrder: number[]) => {
    if (playerIdsInOrder.length % 2 !== 0 || playerIdsInOrder.length < 2)
        return [] as { teamA: number[]; teamB: number[] }[];

    const teamSize = playerIdsInOrder.length / 2;
    const first = playerIdsInOrder[0];
    const remaining = playerIdsInOrder.slice(1);
    const result: { teamA: number[]; teamB: number[] }[] = [];

    const walk = (start: number, needed: number, prefix: number[]) => {
        if (needed === 0) {
            const teamA = [first, ...prefix];
            const teamASet = new Set(teamA);
            const teamB = playerIdsInOrder.filter(
                (playerId) => !teamASet.has(playerId),
            );
            result.push({ teamA, teamB });
            return;
        }

        for (let index = start; index <= remaining.length - needed; index++) {
            walk(index + 1, needed - 1, [...prefix, remaining[index]]);
        }
    };

    walk(0, teamSize - 1, []);
    return result;
};

const resolveSelectedRows = (
    selectedPlayerIds: number[],
    adminRows: OutcomePlayerType[],
): OutcomePlayerType[] =>
    selectedPlayerIds.map((playerId) => {
        const row = adminRows.find((outcome) => outcome.playerId === playerId);
        if (!row)
            throw new Error(
                `Selected player ${playerId} is missing from admin rows.`,
            );
        return row;
    });

const buildCandidates = async ({
    gameDayId,
    gameYear,
    history,
    selectedPlayerIds,
    adminRows,
}: {
    gameDayId: number;
    gameYear: number;
    history: number;
    selectedPlayerIds: number[];
    adminRows: OutcomePlayerType[];
}): Promise<Candidate[]> => {
    const selectedRows = resolveSelectedRows(selectedPlayerIds, adminRows);

    const candidates = await Promise.all(
        selectedRows.map(async (row) => {
            const totalPlayed =
                await outcomeService.getPlayerGamesPlayedBeforeGameDay(
                    row.playerId,
                    gameDayId,
                );
            const played = Math.min(10, totalPlayed ?? 0);
            const average = await outcomeService.getRecentAverage(
                gameDayId,
                row.playerId,
                history,
            );
            const born = row.player.born ?? null;
            const age = born !== null && born < 1995 ? gameYear - born : null;
            return {
                playerId: row.playerId,
                goalie: row.goalie === true,
                played,
                average,
                age,
            } satisfies Candidate;
        }),
    );

    return candidates;
};

const buildCandidatesUsingPlayedAllTime = async ({
    gameDayId,
    gameYear,
    history,
    selectedPlayerIds,
    adminRows,
}: {
    gameDayId: number;
    gameYear: number;
    history: number;
    selectedPlayerIds: number[];
    adminRows: OutcomePlayerType[];
}): Promise<Candidate[]> => {
    const selectedRows = resolveSelectedRows(selectedPlayerIds, adminRows);

    const candidates = await Promise.all(
        selectedRows.map(async (row) => {
            const played = Math.min(
                10,
                await outcomeService.getPlayerGamesPlayed(row.playerId),
            );
            const average = await outcomeService.getRecentAverage(
                gameDayId,
                row.playerId,
                history,
            );
            const born = row.player.born ?? null;
            const age = born !== null && born < 1995 ? gameYear - born : null;
            return {
                playerId: row.playerId,
                goalie: row.goalie === true,
                played,
                average,
                age,
            } satisfies Candidate;
        }),
    );

    return candidates;
};

