            };
            writePayloads.push(data);
            return Promise.resolve({
                id: 0,
                gameDayId: data.gameDayId,
                playerId: data.playerId,
                team: data.team,
            } as OutcomeType);
        },
    },
    sendEmailToAllActivePlayers: () =>
        Promise.resolve({ recipientCount: 0 }),
    getPublicBaseUrl: () => 'https://www.toastboy.co.uk',
});

const actualTeamA = historicallyPicked
    .filter((row) => row.team === 'A')
    .map((row) => row.playerId);
const actualTeamB = historicallyPicked
    .filter((row) => row.team === 'B')
    .map((row) => row.playerId);

const predictedAssignments = new Map<number, 'A' | 'B'>();
for (const payload of writePayloads) {
    if (payload.gameDayId !== gameDayId) continue;
    if (payload.team === 'A' || payload.team === 'B') {
        predictedAssignments.set(
            payload.playerId,
            payload.team,
        );
    }
}

const predictedTeamA = Array.from(
    predictedAssignments.entries(),
)
    .filter(([, team]) => team === 'A')
    .map(([playerId]) => playerId);
const predictedTeamB = Array.from(
    predictedAssignments.entries(),
)
    .filter(([, team]) => team === 'B')
    .map(([playerId]) => playerId);

const sameDirect =
    sameTeamSet(predictedTeamA, actualTeamA) &&
    sameTeamSet(predictedTeamB, actualTeamB);
const sameSwapped =
    sameTeamSet(predictedTeamA, actualTeamB) &&
    sameTeamSet(predictedTeamB, actualTeamA);

if (!sameDirect && !sameSwapped) {
    const missedFromA = actualTeamA.filter(
        (playerId) =>
            !predictedTeamA.includes(playerId) &&
            !predictedTeamB.includes(playerId),
    );
    const missedFromB = actualTeamB.filter(
        (playerId) =>
            !predictedTeamA.includes(playerId) &&
            !predictedTeamB.includes(playerId),
    );
    const selectedPlayerIdsInOrder = selectedInput.map(
        (item) => item.playerId,
    );
    const adminRows =
        await outcomeService.getAdminByGameDay(gameDayId);
    const history = gameDay.pickerGamesHistory ?? 10;
    const candidates = await buildCandidates({
        gameDayId,
        gameYear: gameDay.year,
        history,
        selectedPlayerIds: selectedPlayerIdsInOrder,
        adminRows,
    });
    const byPlayerId = new Map(
        candidates.map((candidate) => [
            candidate.playerId,
            candidate,
        ]),
    );
    const knownAges = candidates
        .map((candidate) => candidate.age)
        .filter((age): age is number => age !== null);
    const unknownAgeValue =
        knownAges.length > 0
            ? sum(knownAges) / knownAges.length
            : 0;

    const actualTuple = diffTuple(
        actualTeamA,
        actualTeamB,
        byPlayerId,
        unknownAgeValue,
    );
    const predictedTuple = diffTuple(
        predictedTeamA,
        predictedTeamB,
        byPlayerId,
        unknownAgeValue,
    );
    const canRankByExhaustiveSearch =
        selectedPlayerIdsInOrder.length % 2 === 0;

    selectedPlayerIdsInOrder.length % 2 === 0;
const allSplits = canRankByExhaustiveSearch
    ? uniqueSplits(selectedPlayerIdsInOrder).map(
          (split) => ({
              ...split,
              tuple: diffTuple(
                  split.teamA,
                  split.teamB,
                  byPlayerId,
                  unknownAgeValue,
              ),
          }),
      )
    : [];
const sortedSplits = allSplits
    .slice()
    .sort((left, right) =>
        compareTuple(left.tuple, right.tuple),
    );
const bestTuple = sortedSplits[0]?.tuple ?? null;
const splitsAtBestTuple = bestTuple
    ? sortedSplits.filter(
          (split) =>
              compareTuple(split.tuple, bestTuple) === 0,
      )
    : [];
const betterThanActual = canRankByExhaustiveSearch
    ? sortedSplits.filter(
          (split) =>
              compareTuple(split.tuple, actualTuple) < 0,
      ).length
    : null;
const equalToActual = canRankByExhaustiveSearch
    ? sortedSplits.filter(
          (split) =>
              compareTuple(split.tuple, actualTuple) === 0,
      ).length
    : null;

const candidatesPlayedAllTime =
    await buildCandidatesUsingPlayedAllTime({
        gameDayId,
        gameYear: gameDay.year,
        history,
        selectedPlayerIds: selectedPlayerIdsInOrder,
        adminRows,
    });
const byPlayerIdPlayedAllTime = new Map(
    candidatesPlayedAllTime.map((candidate) => [
        candidate.playerId,
        candidate,
    ]),
);
const knownAgesPlayedAllTime = candidatesPlayedAllTime
    .map((candidate) => candidate.age)
    .filter((age): age is number => age !== null);
const unknownAgeValuePlayedAllTime =
    knownAgesPlayedAllTime.length > 0
        ? sum(knownAgesPlayedAllTime) /
          knownAgesPlayedAllTime.length
        : 0;
const actualTuplePlayedAllTime = diffTuple(
    actualTeamA,
    actualTeamB,
    byPlayerIdPlayedAllTime,
    unknownAgeValuePlayedAllTime,
);
const predictedTuplePlayedAllTime = diffTuple(
    predictedTeamA,
    predictedTeamB,
    byPlayerIdPlayedAllTime,
    unknownAgeValuePlayedAllTime,
);
const allSplitsPlayedAllTime = canRankByExhaustiveSearch
    ? uniqueSplits(selectedPlayerIdsInOrder).map(
          (split) => ({
              ...split,
              tuple: diffTuple(
                  split.teamA,
                  split.teamB,
                  byPlayerIdPlayedAllTime,
                  unknownAgeValuePlayedAllTime,
              ),
          }),
      )
    : [];
const sortedSplitsPlayedAllTime = allSplitsPlayedAllTime
    .slice()
    .sort((left, right) =>
        compareTuple(left.tuple, right.tuple),
    );
const bestTuplePlayedAllTime =
    sortedSplitsPlayedAllTime[0]?.tuple ?? null;
const betterThanActualPlayedAllTime =
    canRankByExhaustiveSearch
        ? sortedSplitsPlayedAllTime.filter(
              (split) =>
                  compareTuple(
                      split.tuple,
                      actualTuplePlayedAllTime,
                  ) < 0,
          ).length
        : null;

console.error(
    JSON.stringify(
        {
            gameDayId,
            actual: {
                teamA: sorted(actualTeamA),
                teamB: sorted(actualTeamB),
            },
            predicted: {
                teamA: sorted(predictedTeamA),
                teamB: sorted(predictedTeamB),
            },
            unmatchedPlayers: {
                actualOnlyTeamA: sorted(missedFromA),
                actualOnlyTeamB: sorted(missedFromB),
            },

                                },
                                diagnostics: {
                                    gameDayPickerGamesHistory:
                                        gameDay.pickerGamesHistory,
                                    historyUsedByPickerCode: history,
                                    inputOrder: selectedPlayerIdsInOrder,
                                    actualTuple,
                                    predictedTuple,
                                    bestTuple,
                                    canRankByExhaustiveSearch,
                                    betterThanActual,
                                    equalToActual,
                                    splitsAtBestTupleCount:
                                        splitsAtBestTuple.length,
                                    candidateSnapshot: candidates
                                        .slice()
                                        .sort(
                                            (left, right) =>
                                                left.playerId - right.playerId,
                                        ),
                                    firstBestSplits: splitsAtBestTuple
                                        .slice(0, 5)
                                        .map((split) => ({
                                            teamA: sorted(split.teamA),
                                            teamB: sorted(split.teamB),
                                            tuple: split.tuple,
                                        })),
                                    alternatePlayedAllTime: {
                                        actualTuple: actualTuplePlayedAllTime,
                                        predictedTuple:
                                            predictedTuplePlayedAllTime,
                                        bestTuple: bestTuplePlayedAllTime,
                                        betterThanActual:
                                            betterThanActualPlayedAllTime,
                                    },
                                },
                            },
                            null,
                            2,
                        ),
                    );
                }

                expect(sameDirect || sameSwapped).toBe(true);
            });
        }
    },
);

