 * gameDay, most recent first.
 * @throws An error if there is a failure.
 */
async getAllForYear(
    year: number,
    untilGameDay?: number,
): Promise<OutcomeType[]> {
    return prisma.outcome.findMany({
        where: {
            gameDay: {
