async getGameDayIdsWithTeamsPicked(): Promise<number[]> {
    const groups = await prisma.outcome.groupBy({
        by: ['gameDayId'],
        where: { team: { not: null } },
        _count: { team: true },
        having: { team: { _count: { gt: 1 } } },
        orderBy: { gameDayId: 'asc' },
    });
    return groups.map((group) => group.gameDayId);
}

